/* One radar icon: its texture, its rectangle in that texture and its hot spot. */
typedef struct {
    short tex;
    short u;
    short v;
    short w;
    short h;
    short fA;
    short x;
    short y;
} Icon312BD8;
extern Icon312BD8 l11_ship_radar_icon_definitions[];

/* Draws one moby's icon on the radar: its offset from the viewer turned into the radar's frame, faded near the rim. */
void draw_ship_radar_moby_icon(char *rot, char *from, char *moby, int icon, long color) {
    float turn[4];
    float mat[16];
    float delta[4];
    float pos[4];
    float len;
    float side;
    int x, y;
    Icon312BD8 *t;

    qzero(turn);
    turn[2] = *(float *)(rot + 8);
    if (*(float *)(rot + 4) > 1.5707964f || *(float *)(rot + 4) < -1.5707964f) {
        turn[2] = -turn[2];
    }
    turn[2] = FastSubRots(1.5707964f, turn[2]);
    euler_to_matrix(mat, turn);
    FastVecSub(delta, moby + 0x10, from);
    delta[2] = 0.0f;
    transform_vector(pos, delta, mat);
    FastVecScale(pos, pos, 0.142857149f);
    len = FastVecLength(pos);
    side = 1.0f;
    if (draw_map51[0] != 0) {
        side = -1.0f;
    }
    x = truncate_float_to_s32_r(side * pos[0]);
    y = truncate_float_to_s32_r(-pos[1]);
    if (len < 46.0f) {
        if (len > 38.0f) {
            float f;
            len = 46.0f - len;
            f = IntToFloat(((unsigned long)color >> 24) & 0xFF) * len;
            color &= 0xFFFFFF;
            color = (truncate_float_to_s32_r(f * 0.125f) << 24) | color;
        }
        t = &l11_ship_radar_icon_definitions[icon];
        y -= 0x50;
        y += frame_size;
        x += 0x1B0;
        DrawTexturedQuad(x - t->x, y - t->y, t->w, t->h, t->u, t->v, t->w, t->h, color, GetEffectTex(t->tex));
    }
}

