extern int collect_oil_tanker_chain_mobys(char *moby, void **out);

// finds the closest candidate moby among those listed for a type
void *select_ship_lock_on_target(void *a0, char *a1, int a2, int a3, void *a4) {
    void *best = 0;
    float bestd = 1000.0f;
    short *p;
    void *list[12];
    count_active_and_visible_listed_mobys(a0, a1 + 0xE8, a1 + 0xEA);
    if (a4 != 0) {
        if (compute_ship_target_reticle_distance_squared(a0, a4) < bestd)
            return a4;
    }
    p = pokitaru_moby_groups[*(short *)(a1 + 0x108)];
    if (p == 0)
        return 0;
    do {
        char *m = (char *)(((*(unsigned short *)p & 0x7FFF) << 8) + pokitaru_mobys_m);
        if (m[0x20] >= 0) {
            int n = collect_oil_tanker_chain_mobys(m, list);
            int i;
            for (i = 1; i < n; i++) {
                float d = compute_ship_target_reticle_distance_squared(a0, list[i]);
                if (d < bestd) {
                    best = list[i];
                    bestd = d;
                }
            }
        }
    } while (*p++ >= 0);
    return best;
}

extern int truncate_float_to_s32_r(float) __asm__("func_001FA898");
extern char ship_target_projection_offset_reference[];

/* squared distance from a point to a projected target, or a large value when out of range */
float compute_ship_target_reticle_distance_squared(void *moby_v, void *o_v) {
    char *moby = moby_v;
    char *o = o_v;
    struct ShipVars *data = (struct ShipVars *)((Moby *)moby)->pvars;
    if (*(unsigned char *)(o + 0x31) != 0) {
        char v[16];
        int ax, ay, cx, cy;
        int dx, dy, t;
        project_world_point_to_screen_pixels(o + 0x10, &ax, &ay, 0);
        dx = ax - data->reticle_x;
        dy = ay - data->reticle_y;
        if (dx < 0)
            dx = -dx;
        if (dy < 0)
            dy = -dy;
        qcopy(v, ship_target_projection_offset_reference);
        FastVecScale(v, ship_target_projection_offset_reference, *(float *)(o + 0xC) / 1280.0f);
        FastVecAdd(v, v, o + 0x10);
        project_world_point_to_screen_pixels(v, &cx, &cy, 0);
        cx = cx - ax;
        cy = cy - ay;
        t = truncate_float_to_s32_r(square_root(IntToFloat(cx * cx + cy * cy))) + 0x1C;
        if (dx < t && dy < t)
            return (float)(dx * dx + dy * dy);
    }
    return 10000.0f;
}
/* counts the listed mobys of the type that are active, and of those the ones with 0x31 set */
void count_active_and_visible_listed_mobys(void *a0, void *a1, void *a2) {
    struct ShipVars *d = (struct ShipVars *)((Moby *)a0)->pvars;
    int type = d->target_group;
    short *p;
    *(unsigned short *)a1 = 0;
    *(unsigned short *)a2 = 0;
    p = pokitaru_moby_groups[type];
    if (p == 0)
        return;
    do {
        int off = (*(unsigned short *)p & 0x7FFF) << 8;
        if (((char *)pokitaru_mobys_m)[off + 0x20] >= 0) {
            (*(unsigned short *)a1)++;
            if (((unsigned char *)pokitaru_mobys_m)[off + 0x31] != 0) {
                (*(unsigned short *)a2)++;
            }
        }
    } while (*p++ >= 0);
}

