/* Draws the Pokitaru jet HUD: frame halves, a marker on every candidate target, ammo icons, gauge sprites and the
   lock-on marker; plays the low-health, low-ammo and idle help messages and refreshes the gauge colour table. */
void draw_ship_hud(char *moby) {
    struct ShipVars *d = (struct ShipVars *)((Moby *)moby)->pvars;
    char *s;
    short *p;
    struct Hero *base;
    struct Hero *g;
    void *list[12];
    int sp40;
    int sp44;
    int tex;
    int i;
    unsigned char n;
    unsigned char c;
    int j;
    int x;
    int y;
    int ex;
    int ey;
    int a;
    int v;
    int lo;
    int hi;
    int idx;
    int per;
    float t;
    float k;
    float m;
    float f;
    float q;

    VU1_addGSregister(0x42, 0x8000000044L);
    DrawTexturedQuad(0x170, (s = g_screen_extent, *(int *)(s + 4)) - 0x90, 0x80, 0x80, 0, 0, 0x80, 0x80, 0x70808080,
                     GetEffectTex_l(0x3C));
    DrawTexturedQuad(0x170, *(int *)(s + 4) - 0x90, 0x80, 0x80, 0, 0, 0x80, 0x80, 0x70808080, GetEffectTex_l(0x3D));
    VU1_addGSregister(0x42, 0x8000000048L);
    GetEffectTex(0x3E);
    p = pokitaru_moby_groups[d->target_group];
    if (p != 0) {
        do {
            char *o = (char *)(((*(unsigned short *)p & 0x7FFF) << 8) + pokitaru_mobys_m);
            if (o[0x20] >= 0) {
                int cnt = collect_oil_tanker_chain_mobys(o, list);
                int w;
                for (w = 0; w < cnt; w++) {
                    draw_ship_radar_moby_icon((char *)pokitaru_camera_rot, (char *)(pokitaru_camera_rot - 4), list[w],
                                              0, 0x75808080);
                }
            }
        } while (*p++ >= 0);
    }
    y = 0x40;
    x = 0x18;
    base = (struct Hero *)g_hero;
    i = 0;
    if (base->ship_ammo_max != 0) {
        do {
            g = (struct Hero *)g_hero;
            if (i < g->ship_ammo) {
                append_scaled_screen_triangle_strip(x, y, 0.5f, ship_hud_missile_pip, 0x19, 0xFFFFF3, 0x50008F00);
            } else {
                append_scaled_screen_triangle_strip(x, y, 0.5f, ship_hud_missile_pip, 0x19, 0xFFFFF3, 0x20004F00);
            }
            n = g->ship_ammo_max;
            if (i == n >> 1) {
                y = 0x2E;
                x += 0x1E;
            }
            y += 0x12;
            i++;
        } while (i < n);
    }
    ex = d->reticle_x;
    ey = d->reticle_y;
    tex = GetEffectTex(0x11);
    append_rotated_sprite_quad(ex, ey, 40.0f, 40.0f, 0.0f, 0x3F, 0x3F, tex, 0xFFFFF3, 0xFF20FF20, 0, 0, 0.5f, 0.5f);
    tex = GetEffectTex(0x12);
    append_rotated_sprite_quad(ex, ey, 40.0f, 40.0f, 0.0f, 0x3F, 0x3F, tex, 0xFFFFF3, 0xFF20FF20, 0, 0, 0.5f, 0.5f);
    tex = GetEffectTex(8);
    append_rotated_sprite_quad(ex, ey, 10.0f, 10.0f, 0.0f, 0x1F, 0x1F, tex, 0xFFFFF3, 0xFF20FF20, 0, 0, 0.5f, 0.5f);
    update_ship_lock_on_target((int)moby, ((char *)d));
    if (d->target != 0) {
        project_world_point_to_screen_pixels(*(char **)&d->target + 0x10, &sp40, &sp44, 0);
        if (d->target_timer > lock_hold_frames) {
            t = IntToFloat(d->target_timer - lock_hold_frames);
            t = t / IntToFloat(lock_fade_frames);
            m = 2.0f * (1.0f - t);
            k = t * 5.0f + 1.0f;
            if (m > 1.0f)
                m = 1.0f;
            c = truncate_float_to_s32_r(m * 96.0f);
            draw_quarter_turn_textured_quads(IntToFloat(sp40), IntToFloat(sp44), k,
                                             normalize_angle(IntToFloat(level_frame) / 30.0f), 0, 0xFF, 0, c);
            d->lock_target = 0;
        } else {
            a = 0xFF;
            if ((d->target_timer / scale_ticks(0x14)) & 1)
                a = 0;
            draw_quarter_turn_textured_quads(IntToFloat(sp40), IntToFloat(sp44), 1.0f, 0.0f, 0xFF, a, 0, 0x60);
            d->lock_target = d->target;
        }
    }
    {
        struct Hero *b = (struct Hero *)g_hero;
        if (b->ship_hp < b->ship_hp_max * 0.25f) {
            int cnt = ((HelpTab *)help_records)->r[0x58].count;
            if (cnt == 0) {
                help_request(0x2AFF, 0x58);
            } else if (cnt < 2) {
                d->lock_counter += 1;
                if (d->lock_counter > scale_ticks(0x708)) {
                    help_request(0x2AFF, 0x58);
                }
            }
        } else if (d->lock_counter != 0) {
            if (((HelpTab *)help_records)->r[0x58].count < 0xFFFF) {
                ((HelpTab *)help_records)->r[0x58].count++;
            }
            per = 600;
            if (scale_ticks(gameplay_event_frame_count) / per > ((HelpTab *)help_records)->r[0x58].best) {
                ((HelpTab *)help_records)->r[0x58].best = scale_ticks(gameplay_event_frame_count) / 600;
            }
            ((HelpTab *)help_records)->r[0x58].flags =
                ((HelpTab *)help_records)->r[0x58].flags | (1 << g_current_level_index) | 0x80000000;
            d->lock_counter = 0;
        }
    }
    fast_dec_timer(&d->hint_timer);
    {
        struct Hero *g2 = (struct Hero *)g_hero;
        if ((g2->ship_ammo < 5 && ((HelpTab *)help_records)->r[0x57].count == 0) ||
            (g2->ship_ammo == 0 && ((HelpTab *)help_records)->r[0x57].count < 2 && d->hint_timer == 0)) {
            help_request(0x2AFE, 0x57);
            d->hint_timer = scale_ticks(0x4B0);
        }
    }
    if (((HelpTab *)help_records)->r[0x56].count == 0) {
        if ((d->idle_timer)++ > scale_ticks(0xE10)) {
            help_request(0x2AFD, 0x56);
        }
    }
    if (((Moby *)moby)->state == 8) {
        FontPrintCenterLarge_c(0x100, 0xC8, 0x80005080L, msg_string(0x5243), 0x11);
    }
    {
        struct Hero *h = (struct Hero *)g_hero;
        f = h->ship_hp - d->hp_shown;
        f *= 0.2f;
        q = absolute_float(f);
        if (q > 1.0f)
            f /= q;
        d->hp_shown += f;
        v = truncate_float_to_s32_r(d->hp_shown * 251.0f / h->ship_hp_max) + 2;
        if (v > 0xFD)
            v = 0xFD;
        if (v < 2)
            v = 2;
        lo = d->hp_bar <= v ? d->hp_bar : v;
        hi = d->hp_bar < v ? v : d->hp_bar;
        for (j = lo; j <= hi; j++) {
            idx = (j & 0xE7) | ((j & 0x10) >> 1) | ((j & 8) << 1);
            if (j < v) {
                (*(int **)&ship_hud_clut)[idx] = ship_hud_clut_backup[idx];
            } else {
                (*(int **)&ship_hud_clut)[idx] = 0x80000000;
            }
        }
        d->hp_bar = v;
    }
}

