/* turns a moby toward a point and, while in range, spawns a puff */
void update_moby_target_heading_and_conditional_movement(char *m, float *p) {
    struct PuffoidVars *data = (struct PuffoidVars *)((Moby *)m)->pvars;
    float v[3];
    char tmp[16];
    float ang = fast_atan2(p[0] - ((Moby *)m)->pos.x, p[1] - ((Moby *)m)->pos.y);
    float t = FastAddRots(ang, data->heading_offset);
    float dist;
    float b = g_frame_time_sq * 8.726646f;
    SteerAngleWithVelocity((float *)(m + 0x48), &data->turn_vel, t, b, b, g_frame_time_r * 12.566371f);
    dist = compute_interpolated_record_value(m);
    if (((Moby *)m)->seq == ((Moby *)m)->prev_seq) {
        if (8.0f < dist && dist < 22.0f) {
            data->walk_speed = l11_puffoid_horizontal_speed_limit * *(float *)&g_frame_time_s;
            v[0] = FastCos(((Moby *)m)->rot.z) * 2;
            v[1] = FastSin(((Moby *)m)->rot.z) * 2;
            v[2] = 0;
            MobySteerToward(m, (char *)&data->move_ctx, v, tmp, 1.0f);
        }
    }
}
/* Counts the Puffoid mobys in this moby's group that are in states 13..17. */
short count_group_puffoid_mobys_in_states_13_to_17(struct Moby *self_) {
    struct Moby *self = (struct Moby *)self_;
    unsigned short *p;
    short n;
    char *base;

    if (self->group == 0xFF)
        return 0;
    p = (unsigned short *)pokitaru_moby_groups[self->group];
    n = 0;
    if (p == 0)
        return 0;
    base = pokitaru_mobys;
    for (;;) {
        struct Moby *moby = (struct Moby *)(base + ((*p & 0x7FFF) << 8));
        if (moby->oclass == MOBY_CLASS_PUFFOID) {
            if (moby->state >= 13) {
                if (moby->state < 18)
                    n++;
            }
        }
        if ((short)*p++ < 0)
            return n;
    }
}
