/* Moby update for a two-leaf gate that spawns and swings open its leaves. */
void two_door_gate_update(struct PMoby *moby) {
    struct L11GateVars *d = (struct L11GateVars *)moby->pvars;
    float v[4];

    switch (moby->state) {
        case 0: {
            struct PMoby *c;
            struct PMoby *r;
            u8 *pv;
            moby->scale *= 2.0f;
            d->left = (struct PMoby *)CreateMoby(0x4DF);
            d->left->draw_dist = 0x40;
            d->left->visible = 1;
            d->left->spawn_frame = ((struct PMoby *)hero_x.moby)->spawn_frame;
            d->left->flags = moby->flags | 0x20;
            c = d->left;
            qcopy(&c->pos, &moby->pos);
            c->pos.z -= 4.0f;
            r = d->left;
            qcopy(&r->rot, &moby->rot);
            {
                float qx = (two_door_gate_tilt_deg) * 0.017453292f;
                float qy = (two_door_gate_open_angle_deg) * 0.017453292f;
                r->rot.x = -qx;
                d->left->rot.y = qy;
            }
            pv = d->left->pvars;
            *(u8 **)(pv + 8) = pv + 0x20;
            *(u32 *)(pv + 0x5C) |= 1;
            d->right = (struct PMoby *)CreateMoby(0x4DF);
            d->right->draw_dist = 0x40;
            d->right->visible = 1;
            d->right->spawn_frame = ((struct PMoby *)hero_x.moby)->spawn_frame;
            d->right->flags = moby->flags | 0x8020;
            c = d->right;
            qcopy(&c->pos, &moby->pos);
            c->pos.z -= 4.0f;
            r = d->right;
            qcopy(&r->rot, &moby->rot);
            {
                float qx = (two_door_gate_tilt_deg) * 0.017453292f;
                float qy = (two_door_gate_open_angle_deg) * 0.017453292f;
                r->rot.x = qx;
                d->right->rot.y = qy;
            }
            pv = d->right->pvars;
            *(u8 **)(pv + 8) = pv + 0x20;
            *(u32 *)(pv + 0x5C) |= 1;
            moby->state = 1;
            break;
        }
        case 1:
            if (vec_distance_xy(&moby->pos.x, (float *)&hero_x.motion.pos) < 12.0f &&
                is_point_inside_clip_volume(&hero_x.motion.pos, d->unk10) != 0) {
                d->t = 0.0f;
                moby->state = 2;
                Moby_PlaySound(0, 4, (int)d->left);
            }
            break;
        case 2:
            ApproachWithVelocity(&d->t, &d->speed, 1.0f, g_frame_time_sq * 8.0f, g_frame_time_sq * 16.0f,
                                 g_frame_time * 8.0f);
            vec_scale_to_length(v, &moby->rot_row0, 0.5f);
            FastVecAdd(&d->left->pos, &moby->pos, v);
            d->left->pos.z = moby->pos.z + d->t * 4.0f - 4.0f;
            FastVecAdd(&d->right->pos, &moby->pos, v);
            d->right->pos.z = moby->pos.z + d->t * 4.0f - 4.0f;
            moby_build_matrix(d->left);
            moby_build_matrix(d->right);
            if (d->t >= 1.0f) {
                d->t = 0.0f;
                moby->state = 3;
            }
            break;
        case 3: {
            float a;
            ApproachWithVelocity(&d->t, &d->speed, 1.0f, g_frame_time_sq * 10.0f, g_frame_time_sq * 20.0f,
                                 g_frame_time * 10.0f);
            a = (1.0f - d->t) * ((two_door_gate_open_angle_deg) * 0.017453292f);
            d->left->rot.y = a;
            d->right->rot.y = a;
            moby_build_matrix(d->left);
            moby_build_matrix(d->right);
            if (d->t >= 1.0f) {
                d->t = 0.0f;
                moby->state = 4;
            }
            break;
        }
        case 4: {
            float a;
            ApproachWithVelocity(&d->t, &d->speed, 1.0f, g_frame_time_sq * 12.0f, g_frame_time_sq * 24.0f,
                                 g_frame_time * 12.0f);
            d->left->pos.z = moby->pos.z + d->t * 0.25f;
            d->right->pos.z = moby->pos.z + d->t * 0.25f;
            a = d->t * 1.5707964f;
            d->left->rot.x = -a;
            d->right->rot.x = a;
            moby_build_matrix(d->left);
            moby_build_matrix(d->right);
            if (d->t >= 1.0f) {
                d->t = 0.0f;
                moby->state = 5;
            }
            break;
        }
        case 5:
            break;
        case 6:
            vec_scale_to_length(v, &moby->rot_row0, 0.5f);
            FastVecAdd(&d->left->pos, &moby->pos, v);
            {
                float pz = moby->pos.z + (two_door_gate_door_height);
                float qx = (two_door_gate_tilt_deg) * 0.017453292f;
                float qy = (two_door_gate_open_angle_deg) * 0.017453292f;
                d->left->pos.z = pz;
                d->left->rot.x = -qx;
                d->left->rot.y = qy;
            }
            moby_build_matrix(d->left);
            FastVecAdd(&d->right->pos, &moby->pos, v);
            {
                float pz = moby->pos.z + (two_door_gate_door_height);
                float qx = (two_door_gate_tilt_deg) * 0.017453292f;
                float qy = (two_door_gate_open_angle_deg) * 0.017453292f;
                d->right->pos.z = pz;
                d->right->rot.x = qx;
                d->right->rot.y = qy;
            }
            moby_build_matrix(d->right);
            break;
    }
}
