/* UpdateMoby_1264: switch on the state byte at +0x20. State 0 deletes the moby if its entry is 0xFF in the table at
 * help_stats_base + 0xAA35; otherwise it creates eight objects of type 0x4F1 (CreateMoby), kept at data + 0x70, copies
 * the
 * moby's position and angles into each, and moves to state 1. States 1 and 2 step the table index at data + 0x60 and
 * update the eight objects. */
typedef struct OilChainVars {
    u8 pad00[0x60];
    s32 path_index; /* 0x60 */
    s32 count; /* 0x64 */
    s32 point; /* 0x68 */
    union {
        f32 f;
        s32 i;
    } t; /* 0x6C: zeroed as an int, read as a float */
    struct Moby *links[8]; /* 0x70 */
    s16 offsets[8]; /* 0x90 */
    u8 pad_A0[0x20]; /* 0xA0: frac[8], not used here */
    f32 catchup[8]; /* 0xC0 */
    f32 health; /* 0xE0 */
    u8 pad_E4[0x8];
    s32 path_sel; /* 0xEC */
    char *path; /* 0xF0 */
    s32 sound; /* 0xF4 */
} OilChainVars;

/* Oil tanker front: lays out its chain along a path, then moves along it and handles damage. */
void oil_tanker_front_update(char *moby) {
    OilChainVars *chain_vars = (OilChainVars *)((struct Moby *)moby)->pvars;
    int st = ((struct Moby *)moby)->state;
    switch (st) {
        case 0: {
            char *p;
            struct Moby **q;
            short *h;
            int *z;
            int i;
            distribute_group_blarg_ship_1319_mobys_along_path(moby, chain_vars->path_index);
            if (((unsigned char *)saved_mission_state)[((struct Moby *)moby)->mission + (map_data_0015EE84 << 4)] ==
                0xFF) {
                DeleteMoby(moby);
                return;
            }
            ((struct Moby *)moby)->update_dist = 0xFF;
            ((struct Moby *)moby)->draw_dist = 0x200;
            p = ((char **)l11_paths)[chain_vars->path_sel];
            chain_vars->path = p;
            qcopy(&((struct Moby *)moby)->pos, p + 0x10);
            chain_vars->health = 80.0f;
            chain_vars->count = 8;
            chain_vars->sound = -1;
            chain_vars->point = 0;
            chain_vars->t.i = 0;
            ((struct Moby *)moby)->state = 1;
            z = (int *)chain_vars->catchup;
            h = chain_vars->offsets;
            q = chain_vars->links;
            for (i = 7; i >= 0; i--) {
                struct Moby *s = (struct Moby *)CreateMoby(0x4F1);
                struct Moby *t;
                *q = s;
                s->draw_dist = 0x200;
                (*q)->update_dist = 0xFF;
                (*q)->visible = 1;
                (*q)->spawn_frame = ((struct Moby *)moby)->spawn_frame;
                (*q)->flags = ((struct Moby *)moby)->flags & 0xFFDF;
                (*q)->scale = (*q)->pclass->scale * 2.0f;
                t = *q;
                qcopy(&t->pos, &((struct Moby *)moby)->pos);
                qcopy(&t->rot, &((struct Moby *)moby)->rot);
                *h = *(unsigned short *)chain_vars->path - 100;
                *z = 0;
                q++;
                h++;
                z++;
            }
            return;
        }
        case 1:
            if (((struct Hero *)g_hero)->state.current == 0x32) {
                int *z = (int *)chain_vars->catchup;
                short *h = chain_vars->offsets;
                int i;
                ((struct Moby *)moby)->state = 2;
                chain_vars->path = ((char **)l11_paths)[chain_vars->path_index];
                chain_vars->point = 0;
                for (i = 7; i >= 0; i--) {
                    *h = *(unsigned short *)chain_vars->path - 100;
                    *z = 0;
                    h++;
                    z++;
                }
            }
            /* fall through */
        case 2: {
            float f = chain_vars->t.f + oil_tanker_path_step;
            float *z;
            struct Moby **q;
            float *zz;
            int i;
            chain_vars->t.f = f;
            if (1.0f < f) {
                chain_vars->t.f = f - 1.0f;
                chain_vars->point = (chain_vars->point + 1) % *(s32 *)chain_vars->path;
            }
            z = chain_vars->catchup;
            q = chain_vars->links;
            zz = z;
            for (i = 7; i >= 0; i--) {
                float old = *z;
                ApproachValue(zz, 0.0f, g_frame_time * 5.0f);
                if (old != 0.0f && *z == 0.0f) {
                    if (*q != 0)
                        Moby_PlaySound(0, 0, *q);
                }
                q++;
                zz++;
                z++;
            }
            update_oil_tanker_front_path_pose(moby);
            update_oil_tanker_link_path_poses(moby);
            if (((struct Moby *)moby)->state == 2)
                process_oil_tanker_damage_and_destruction(moby);
            if (voice_is_playing(moby, chain_vars->sound) == 0) {
                chain_vars->sound = Moby_PlaySound(0, 4, (int)moby);
            }
            break;
        }
    }
}

/* Orients a moby along a path of three points read from its data table. */
void update_oil_tanker_front_path_pose(char *moby) {
    Moby *m = (Moby *)moby;
    OilChainVars *chain_vars = (OilChainVars *)m->pvars;
    int i = chain_vars->point;
    char *path = chain_vars->path;
    int path_point_count;
    float current_path_point[4];
    float next_path_point[4];
    float lookahead_path_point[4];
    float *pb;
    float *pc;
    float x, y, z;
    qcopy(current_path_point, path + i * 16 + 0x10);
    path_point_count = *(int *)path;
    qcopy(pb = next_path_point, path + (i + 1) % path_point_count * 16 + 0x10);
    qcopy(pc = lookahead_path_point, path + (i + 2) % path_point_count * 16 + 0x10);
    x = fast_atan2(current_path_point[0] - next_path_point[0], current_path_point[1] - next_path_point[1]);
    y = fast_atan2(next_path_point[0] - lookahead_path_point[0], next_path_point[1] - lookahead_path_point[1]);
    z = fast_atan2(vec_distance_xy(current_path_point, pb), next_path_point[2] - current_path_point[2]);
    m->rot.y =
        FastAddRots(FastSubRots(fast_atan2(vec_distance_xy(pb, pc), lookahead_path_point[2] - next_path_point[2]), z) *
                        chain_vars->t.f,
                    z);
    m->rot.z = FastAddRots(FastSubRots(y, x) * chain_vars->t.f, x);
    lerp_vector(&m->pos, current_path_point, pb, chain_vars->t.f);
}

