/* Counts the Blarg Ship mobys in state 5 on id list idx. Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l11/gameplay/vendor/00315968.c, FUN_L11_0031a758. */
short func_L11_0031BBC8_r(int idx) {
    short *p = pokitaru_moby_groups[idx];
    short found = 0;
    short n = 0;
    char *base = pokitaru_mobys_r2;
    do {
        struct Moby *moby = (struct Moby *)((unsigned char *)(((p[0] & 0x7FFF) << 8) + (int)base));
        if (moby->oclass == MOBY_CLASS_BLARG_SHIP_1319 && moby->state == 5) {
            found = ++n;
        }
    } while (*p++ >= 0);
    return found;
}

/* finds the idle moby of type 0x527 in a list and launches it at the hero */
char *activate_listed_blarg_ship(int idx) {
    short *p = pokitaru_moby_groups[idx];
    float v0[4], v1[4], v2[4], v3[4], v4[4], v5[4];
    do {
        int id = *p & 0x7FFF;
        if (*(short *)((id << 8) + pokitaru_mobys_m + 0xA6) == 0x527 &&
            *(unsigned char *)((id << 8) + pokitaru_mobys_m + 0x20) == 4 && random_integer_below(10) == 0) {
            Moby *m;
            struct BlargShipVars *d;
            float a;
            m = (Moby *)((char *)pokitaru_mobys_m + (id << 8));
            d = (struct BlargShipVars *)m->pvars;
            qcopy(v2, pokitaru_camera_rot);
            v2[0] = 0;
            if (v2[1] > 0.17453292f)
                v2[1] = 0.17453292f;
            else if (v2[1] < -0.17453292f)
                v2[1] = -0.17453292f;
            euler_rotation_basis(v3, v2);
            a = FastAddRots(0.7853982f, (float)d->side * 1.5707964f);
            vec_scale_to_length(v0, v4, FastSin(a) * 12.0f);
            FastVecAdd(v1, camera_pos_b358, v0);
            vec_scale_to_length(v0, v5, FastCos(a) * 12.0f);
            FastVecAdd(v1, v1, v0);
            vec_scale_to_length(v0, v3, 6.0f);
            FastVecAdd(v1, v1, v0);
            qcopy(&d->hero_position, &((struct Hero *)g_hero)->motion.pos);
            qcopy(&m->pos, v1);
            m->state = 5;
            m->command = 1;
            d->turn_speed = g_frame_time * 20.0f;
            d->unk_98 = 0;
            d->unk_94 = 5.0f;
            if (m->prev_seq != 0)
                MobyBlendAnimation(m, 0, 0, scale_ticks(10));
            m->flags &= 0xFFFE;
            *(int *)&m->collision = *(int *)(*(char **)&m->pclass + 0x10);
            return (char *)m;
        }
    } while (*p++ >= 0);
    return 0;
}

/* Moby update that deletes itself or shows a banner depending on its data. */
void cleared_group_dialogue_update(char *moby) {
    int *data = ((int *)((Moby *)moby)->pvars);
    if (data[0] == -1) {
        DeleteMoby(moby);
    } else if (data[1] != -1 && count_active_moby_group_members(data[1], -1) == 0) {
        unsigned char *g = gSkillPoints;
        if (g[0x13] == 0) {
            g[0x13] = 1;
            allocate_voice_for_bank_entry(1, 0, 0);
            queue_dialogue_message(0x53DB, -1);
        }
    }
}
